parameters.query:
query webhookQuery($objectid: ID!) {
  node(id: $objectid) {
    ... on Event {
      id
      code
      title
      location { name }
      remoteMeeting { type url }
      staff {
        edges {
          node {
            id
            staffRole { id name }
            contact { id firstName lastName emailAddress }
          }
        }
      }
    }
  }
}

parameters.jsCode:
const node = $json.payload.node;
return [{
  json: {
    status: 'skipped',
    timestamp: $now.toISO(),
    eventId: node.id,
    eventCode: node.code,
    reason: 'Virtual classroom is not configured as Microsoft Teams yet',
  },
}];

const config = $('Config').first().json;
// Comma-separated list, for example "example.com,example.org".
const internalDomains = String(config.INTERNAL_DOMAINS || '')
  .split(',')
  .map(d => d.trim().toLowerCase())
  .filter(Boolean);
const node = $json.payload.node;

const instructors = (node.staff?.edges || [])
  .map(e => e.node)
  .filter(s => s.staffRole?.name === config.INSTRUCTOR_STAFF_ROLE_NAME)
  .map(s => {
    const email = s.contact?.emailAddress || '';
    const domain = email.split('@')[1]?.toLowerCase() || '';
    return {
      staffId: s.id,
      contactId: s.contact?.id,
      name: `${s.contact?.firstName} ${s.contact?.lastName}`,
      email,
      internal: internalDomains.includes(domain),
    };
  });

return [{
  json: {
    eventId: node.id,
    eventCode: node.code,
    eventTitle: node.title,
    remoteMeetingUrl: node.remoteMeeting?.url ?? null,
    instructorsInternal: instructors.filter(i => i.internal),
    instructorsExternal: instructors.filter(i => !i.internal),
  },
}];

const d = $json;
return [{
  json: {
    status: 'no_internal_instructors',
    timestamp: $now.toISO(),
    eventCode: d.eventCode,
    eventTitle: d.eventTitle,
    externalSkipped: d.instructorsExternal,
    note: d.instructorsExternal.length ? 'Only external instructor(s) found so none can be added as Teams co-organizer (no tenant identity).' : 'No staff with the instructor role found on this event.',
  },
}];

// Drop any that failed to resolve (e.g. no Entra account despite an internal email domain) instead of erroring the whole run.
const resolved = $input.all().map(i => i.json).filter(u => u && u.id && !u.error);
return [{ json: { resolvedInstructors: resolved } }];

const organiserMailboxId = $('Config').first().json.ORGANISER_MAILBOX_ID;
const eventInfo = $('Identify Instructors').first().json;
const resolved = $('Collect Resolved Instructors').first().json.resolvedInstructors;
const meetingResp = $json;
const meeting = meetingResp?.value?.[0];

if (!meeting) {
  return [{ json: { error: 'No meeting matched JoinWebUrl filter', eventCode: eventInfo.eventCode, meetingResp } }];
}

const existingAttendees = meeting.participants?.attendees || [];
const resolvedIds = new Set(resolved.map(r => r.id));

const keptAttendees = existingAttendees.filter(a => !resolvedIds.has(a.identity?.user?.id));
const newAttendees = resolved.map(r => ({
  identity: { user: { id: r.id, displayName: r.displayName } },
  upn: r.userPrincipalName,
  role: 'coorganizer',
}));

return [{
  json: {
    organiserMailboxId,
    meetingId: meeting.id,
    eventCode: eventInfo.eventCode,
    eventTitle: eventInfo.eventTitle,
    addedInstructors: resolved.map(r => r.displayName),
    externalSkipped: eventInfo.instructorsExternal.map(i => i.name),
    mergedAttendees: [...keptAttendees, ...newAttendees],
  },
}];

const built = $('Build Merged Attendee List').first().json;
const patchResp = $json;

return [{
  json: {
    timestamp: $now.toISO(),
    status: patchResp.error ? 'error' : 'success',
    eventCode: built.eventCode,
    eventTitle: built.eventTitle,
    addedAsCoorganizer: built.addedInstructors,
    skippedExternal: built.externalSkipped,
    patchError: patchResp.error ?? null,
  },
}];

const eventInfo = $('Identify Instructors').first().json;
const lookup = $json.meetingResp ?? {};
const lookupError = lookup.error ? (typeof lookup.error === 'string' ? lookup.error : lookup.error.message) : null;

return [{
  json: {
    timestamp: $now.toISO(),
    status: 'no_meeting_found',
    eventCode: eventInfo.eventCode,
    eventTitle: eventInfo.eventTitle,
    remoteMeetingUrl: eventInfo.remoteMeetingUrl,
    note: lookupError
      ? `Online meeting lookup failed (${lookupError}), so no co-organisers were added.`
      : 'No Teams meeting owned by the organiser mailbox matched the event join URL, so no co-organisers were added.',
  },
}];
